"popups/SRMCommonDocManage/cdDeleteConfirmModal.html": "<div class=\"modal-backdrop\" id=\"cdDeleteConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"cdDeleteConfirmTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"cdDeleteConfirmTitle\">공통 서류 삭제 시 유의사항</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\"><p class=\"notice-lead\">공통 서류를 삭제하면, 매핑된 정보들이 훼손될 수 있습니다.</p><p>반드시 최고 관리자(시스템 운영자)만 사용해 주세요. 그래도 진행하시겠습니까?</p></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-delete modal-close\">삭제하기</button><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMCommonDocManage/cdDocAddModal.html": "<div class=\"modal-backdrop\" id=\"cdDocAddModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cdDocAddTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"cdDocAddTitle\">서류 추가</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"srm-kv-grid\">\n          <div class=\"srm-kv-row\"><dt>서류 명칭 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control grow\" placeholder=\"20자 이내로 간략히 작성해 주세요.\" maxlength=\"20\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>설명</dt><dd><input type=\"text\" class=\"form-control grow\" placeholder=\"50자 이내로 간략히 작성해 주세요.\" maxlength=\"50\"></dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-primary\" data-close-modal>서류 추가</button><button type=\"button\" class=\"btn-secondary\" data-close-modal>취소</button></div>\n    </div>\n  </div>",
